// DtsBlob.h
//
// Embedded DTS conformance fixture: a real raw DTS (DCA core) elementary stream,
// 2 ch, 44100 Hz. This fixture guards the DTS false-sync hazard: without
// the DecoderFactory sniff carve-out, Mpg123Decoder false-positives on DTS
// payload bytes and opens the file as bogus "MP3". A passing DTS battery
// (codec == Dts, i.e. routed to FfmpegDecoder) is the regression guard. Produced
// once with FFmpeg (the DTS encoder is "dca", marked experimental):
//
//   ffmpeg -f lavfi -i "sine=frequency=440:sample_rate=44100:duration=0.30" \
//          -ac 2 -c:a dca -strict -2 -f dts conf_dts.dts
//   xxd -i conf_dts.dts
//
// Included once, inside ConformanceTest.cpp's anonymous namespace and its
// RAWFORM_HAVE_FFMPEG guard.
